-- AM checkout: preserve all legacy rows; origin.ref is the governed provenance link.
-- Do NOT populate regla_legacy_id: the existing compatibility view hides the legacy on CANDIDATA.
-- All ten enter via the door and are judged honestly. No legacy cutover/automatic publication in this lot.
BEGIN;
DO $pre$
DECLARE x jsonb; actual text;
BEGIN
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas) <> 0 THEN RAISE EXCEPTION 'AM_CHECKOUT_BASE_CHANGED_REJUDGE'; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_rubrica WHERE estado='ACTIVO') <> 7 THEN RAISE EXCEPTION 'AM_CHECKOUT_RUBRIC_CHANGED'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements($amjson$[{"id":155,"codigo":"REG_CHK_001","huella":"326324ac1471bca44a81baf929fbc709"},{"id":156,"codigo":"REG_CHK_002","huella":"841e65181e42b1087aa99dab8c28260b"},{"id":183,"codigo":"REG_TEC_007","huella":"9034eea8fdc39a3e65fb0b454781f022"},{"id":185,"codigo":"REG_TEC_009","huella":"9ccef486b946129e1b39cac7750eaa80"},{"id":207,"codigo":"REG_CHK_003","huella":"f710224b3885c13c109b16f88b2b0af9"},{"id":208,"codigo":"REG_CHK_004","huella":"3996fee2ec3dc573d9381af341d4032a"},{"id":209,"codigo":"REG_CHK_005","huella":"5adf8813e27368280ecaa0eb06b00314"},{"id":210,"codigo":"REG_CHK_006","huella":"14a473aed8fb568318157cd3b7227bd4"},{"id":211,"codigo":"REG_CHK_007","huella":"9eaccb2331b2fd95983c8afe0b564ad2"},{"id":212,"codigo":"REG_CHK_008","huella":"adf7dadc08ace3c32ee2f640ec9b58d0"},{"id":226,"codigo":"REG_NIU_002","huella":"2e1ed3f0a06649a4034d7ab2ff9212b3"},{"id":228,"codigo":"REG_NIU_004","huella":"0e785b019f59cefe88de0e07eec3bafa"},{"id":276,"codigo":"REG_CHK_013","huella":"91c6b0a1d47bad33c24299c0478f1798"},{"id":280,"codigo":"REG_CHK_017","huella":"5bbb22ddc1822eded3b2e34b681af6f4"},{"id":288,"codigo":"REG_CHK_CUO_005","huella":"96497d675e13700c47ce3b3953970a0f"},{"id":292,"codigo":"REG_CHK_CUO_009","huella":"d54d00f78989e5b62bf3d6e8f83937fe"},{"id":316,"codigo":"REG_CHK_026","huella":"ae1ed26a0c69dfa15345da9c8db42037"},{"id":327,"codigo":"REG_SUC_004","huella":"a231473494c4d6f3368fcfc1b70fa186"},{"id":403,"codigo":"B2B-RULE-IDEMP-001","huella":"2e1db64228abe4b5e49d31bd1e25efd8"},{"id":495,"codigo":"REG_ONB003_DNI_RESOLUTION_ATOMIC_001","huella":"485bdfe5191529edc39d6dca6e0e4c3c"},{"id":521,"codigo":"REG_CLIENT_CHECKOUT_AUTODEBIT_CONSENT_CONTEXT_001","huella":"64b79c752efa54359e5c7927e816d5e7"},{"id":523,"codigo":"REG_CLIENT_PAYMENT_OUTCOME_NORMALIZATION_001","huella":"7d220bf5a6890930d882a4f02606b515"},{"id":524,"codigo":"REG_CLIENT_PAYMENT_CONFIRMED_POST_ACTIONS_001","huella":"ea84793c1ad0e4a00e5a5c2dd5840593"},{"id":525,"codigo":"REG_CLIENT_PAYMENT_SUCCESS_VIEW_001","huella":"1829f27fb89c0ca7d4f161b1a556ed34"},{"id":528,"codigo":"REG_CLIENT_INSTALLMENT_PLAN_SNAPSHOT_001","huella":"535cd635f9e522966bdaec43a4c55bcf"},{"id":530,"codigo":"REG_CLIENT_INSTALLMENT_PAYMENT_DUE_001","huella":"8a3af801895851d237713c9dd8449f0a"},{"id":533,"codigo":"REG_CLIENT_DEBT_SETTLEMENT_STATUS_001","huella":"d9800f5b0ab4be42ed361662bffd5904"},{"id":534,"codigo":"REG_CLIENT_NO_DEBT_LETTER_STATUS_001","huella":"ce8cb260d5a4426738f08c0ea907f4a4"},{"id":539,"codigo":"REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001","huella":"1eccb1c84f74240b73bccc0987f8bb9e"},{"id":540,"codigo":"REG_CLIENT_CHECKOUT_PROVIDER_HANDOFF_001","huella":"ad800c503a8e5fec1c67de8218bcdee9"},{"id":543,"codigo":"REG_CLIENT_CHECKOUT_INSTALLMENTS_VIEW_001","huella":"45ca846d731d4c4786d16d3fa8a11055"}]$amjson$::jsonb) LOOP
  SELECT md5(jsonb_build_object('id',id,'codigo',codigo,'categoria',categoria,'titulo',titulo,'descripcion',descripcion,'razon',razon,'valor_config',valor_config,'es_transversal',es_transversal,'estado',estado,'origen',origen)::text)
  INTO actual FROM lf_ops.reglas WHERE id=(x->>'id')::int AND codigo=x->>'codigo';
  IF actual IS DISTINCT FROM x->>'huella' THEN RAISE EXCEPTION 'AM_CHECKOUT_EVIDENCE_DRIFT %',x->>'codigo'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.lf_global_config WHERE scope='AUTH' AND config_key='IDEMPOTENCY_KEY_VALIDITY_MINUTES' AND value_status='REAL' AND valid_from<=now()) THEN RAISE EXCEPTION 'AM_CHECKOUT_NO_REAL_IDEMPOTENCY_CONFIG'; END IF;
END $pre$;
