('modalidad_pago','text','ninguna','Modalidad de pago elegida; hecho lógico piloto.'),
('autoriza_debito_automatico','boolean','ninguna','Consentimiento explícito de cobro automático de cuotas; hecho lógico piloto.'),
('conexion_disponible','boolean','ninguna','Disponibilidad de conexión del dispositivo; hecho lógico piloto.'),
