INSERT INTO lf_ops.nucleo_parametros(scope,config_key,hecho,minimo,dueno)
 VALUES ('AUTH','IDEMPOTENCY_KEY_VALIDITY_MINUTES','edad_clave_idempotencia',1,'TECNICO');
DO $am$
DECLARE item jsonb; p jsonb; j jsonb; g jsonb; jr jsonb; e jsonb; v integer; h text; k text; n integer;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($amjson$[{"paquete":{"codigo":"REG_CHK_002","clave":"total_consolidado","titulo":"Total consolidado del checkout","descripcion":"El total consolidado es la suma del monto de la modalidad elegida en cada oferta seleccionada.","familia":"PAYMENTS_CHECKOUT","naturaleza":"DEFINICION","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"CALCULAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/156","solicitante":"migracion-nucleo"},"condicion":{"op":"suma","lista":{"hecho":"checkout_items"},"campo":"monto_total"},"pruebas":[{"casuistica":"VALOR_TIPICO","entrada":{"checkout_items":[{"monto_total":1200.5},{"monto_total":300}]},"esperado":1500.5},{"casuistica":"VALOR_BORDE","entrada":{"checkout_items":[]},"esperado":0}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"156: cálculo concreto sum(items[].monto_total), resultado observable."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"156 es transversal; CLIENTE hereda en onboarding, home y legal además de checkout; no se prueba aplicabilidad de checkout_items en esos nodos."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica la suma de los importes elegidos."},"COH_EFECTO":{"puntaje":1,"observacion":"CALCULAR coincide con fórmula 156."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"suma de monto_total coincide con valor_config.formula; casos lista con dos montos y vacía."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"REG_CHK_001 es compatible con un resumen consolidado; queda sin demostrar aplicación fuera del checkout y no se validó el origen operativo de los items."},"SEM_NO_DUPLICA":{"puntaje":1,"observacion":"El equivalente 156 es la fuente migrada deliberadamente conservada; no hay otra candidata del núcleo con esa clave ni una fórmula distinta en las reglas de la familia revisadas."}}}},{"paquete":{"codigo":"REG_CHK_004","clave":"cta_pago_reintento","titulo":"El botón de pago no se rehabilita salvo resultado seguro","descripcion":"Tras el primer clic el botón de pago queda bloqueado; solo un resultado normalizado de rechazo confirmado, no enviado o proveedor no disponible antes del envío permite un nuevo intento.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/208,523,228","solicitante":"migracion-nucleo"},"condicion":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_DECLINED_CONFIRMED"}},"der":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_NOT_SUBMITTED"}},"der":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT"}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION"},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED"},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_NOT_SUBMITTED"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"208: bloquear CTA para impedir doble submit."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"208 abarca varias pantallas pero 523 está enlazada a HOME_FAQ; el texto es sobre un intento de checkout y no toda la experiencia CLIENTE."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica bloqueo y resultados que habilitan reintento."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR coincide con bloqueo de CTA."},"COH_TEXTO_CONDICION":{"puntaje":0,"observacion":"Condición solo compara outcomes: no representa primer clic, intento enviado, autorización backend, reserva/quote vigente ni cambio de medio de 208/523. Un estado inicial desconocido queda bloqueado."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"523/REG_CHK_003/REG_CLIENT_CHECKOUT_PROVIDER_HANDOFF_001 exigen backend y quote; el candidato no conserva toda esa protección."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"REG_CHK_003 y PROVIDER_HANDOFF también regulan bloqueo/reintento; la absorción de 523 y 228 no preserva normalización completa."}}}},{"paquete":{"codigo":"REG_CHK_005","clave":"exito_post_pago","titulo":"Pantalla de éxito y efectos post-pago solo con pago confirmado","descripcion":"La pantalla de éxito y los efectos post-pago se ejecutan solo cuando el resultado normalizado es PAYMENT_CONFIRMED.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"PERMITIR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/209,524","solicitante":"migracion-nucleo"},"condicion":{"op":"=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_CONFIRMED"}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED"},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"209/524: permite acciones solo tras confirmación."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"524 es backend por deuda e incluye múltiples modalidades; CLIENTE/PANTALLA no representa todo el procesamiento."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"La puerta de éxito se entiende; pero efectos post-pago no están enumerados."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR condicionado a PAYMENT_CONFIRMED expresa el permiso inicial."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"La condición expresa la autorización inicial pero no per-deuda, activación de plan, origen ledger ni prohibición de modificar onboarding de 209/524."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"REG_CLIENT_INSTALLMENT_PLAN_SNAPSHOT_001 exige snapshot inmutable; no se acredita preservar efectos específicos de 524."},"SEM_NO_DUPLICA":{"puntaje":0,"observacion":"REG_CLIENT_PAYMENT_SUCCESS_VIEW_001 contiene la misma condición de éxito; no se declara consolidación o distinción de ese solapamiento."}}}},{"paquete":{"codigo":"REG_CHK_006","clave":"comision_visible","titulo":"Toda comisión cobrada debe mostrarse antes de pagar","descripcion":"No se acepta una configuración de precios del aliado que cobre una comisión (de gestión o de Niubiz) y la oculte en el checkout. Los porcentajes vienen de la configuración del aliado, no de la regla.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-LEGAL_NORMA","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/210,226","solicitante":"migracion-nucleo"},"condicion":{"op":"o","izq":{"op":"y","izq":{"op":"!=","izq":{"hecho":"COL-public.lf_b2b_pricing_config.niubiz_fee_type"},"der":{"lit":"NONE"}},"der":{"op":"=","izq":{"hecho":"COL-public.lf_b2b_pricing_config.show_niubiz_fee"},"der":{"lit":false}}},"der":{"op":"y","izq":{"op":"!=","izq":{"hecho":"COL-public.lf_b2b_pricing_config.management_fee_type"},"der":{"lit":"NONE"}},"der":{"op":"=","izq":{"hecho":"COL-public.lf_b2b_pricing_config.show_management_fee"},"der":{"lit":false}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"COL-public.lf_b2b_pricing_config.niubiz_fee_type":"PERCENTAGE","COL-public.lf_b2b_pricing_config.show_niubiz_fee":false,"COL-public.lf_b2b_pricing_config.management_fee_type":"NONE","COL-public.lf_b2b_pricing_config.show_management_fee":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"COL-public.lf_b2b_pricing_config.niubiz_fee_type":"NONE","COL-public.lf_b2b_pricing_config.show_niubiz_fee":true,"COL-public.lf_b2b_pricing_config.management_fee_type":"PERCENTAGE","COL-public.lf_b2b_pricing_config.show_management_fee":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"COL-public.lf_b2b_pricing_config.niubiz_fee_type":"PERCENTAGE","COL-public.lf_b2b_pricing_config.show_niubiz_fee":true,"COL-public.lf_b2b_pricing_config.management_fee_type":"NONE","COL-public.lf_b2b_pricing_config.show_management_fee":false},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"210/226: impedir ocultamiento de comisión configurada."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"210 y 226 son visibilidad previa a confirmar en UI, mientras BACKEND valida configuración, no render efectivo."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"La prohibición de configurar comisión oculta es clara; no fija importes."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR configuración no visible es consistente con título."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Solo compara flags; no comprueba visibilidad efectiva antes de confirmar, tamaño legible ni inclusión de comisiones en total (226)."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"La regla de transparencia es compatible, pero 210/226 fijan comisión LF y la configuración actual no; EKB LF-LEGACY-CHECKOUT-COMMISSION-TEXT-VS-CONFIG-20261121-001. No se resuelve el importe."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"210 y 226 son fuentes del solapamiento; no se acredita consolidación íntegra del total y presentación."}}}},{"paquete":{"codigo":"REG_CHK_007","clave":"seleccion_inmutable_confirmacion","titulo":"Selección inmutable en la confirmación","descripcion":"En la pantalla de confirmación el usuario no puede modificar su selección de ofertas.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/211","solicitante":"migracion-nucleo"},"condicion":{"op":"=","izq":{"hecho":"checkout_en_confirmacion"},"der":{"lit":true}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"checkout_en_confirmacion":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"checkout_en_confirmacion":false},"esperado":false}]},"juicio":{"veredicto":"PASS","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"211: bloquear la modificación de la selección y permitir ver resumen/continuar."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"La condición acota a confirmación aunque el nodo CLIENTE es amplio y la legada tiene cobertura parcial; no autoriza efecto fuera de ese contexto."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"La descripción especifica pantalla, acción y sujeto."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR modificación coincide con 211."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"checkout_en_confirmacion=true activa exactamente el bloqueo descrito; false no lo activa."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No se observó contradicción en las 61 reglas de familia y comparadores revisados; snapshot y revalidación de plan son compatibles con inmutabilidad en confirmación."},"SEM_NO_DUPLICA":{"puntaje":1,"observacion":"211 es la fuente intencional de migración; no se detectó otro texto equivalente a prohibir modificar selección en confirmación fuera de ella en las fuentes revisadas."}}}},{"paquete":{"codigo":"REG_CHK_008","clave":"carta_no_adeudo_liquidacion","titulo":"Carta de No Adeudo solo con la deuda liquidada","descripcion":"La Carta de No Adeudo solo puede solicitarse cuando la deuda llegó a SETTLED_CONFIRMED; un pago confirmado (incluido el inicial de un plan en cuotas) no basta.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"PERMITIR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/212,280,292,327","solicitante":"migracion-nucleo"},"condicion":{"op":"=","izq":{"hecho":"estado_liquidacion_deuda"},"der":{"lit":"SETTLED_CONFIRMED"}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"SETTLED_CONFIRMED"},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"PLAN_ACTIVO"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"212/280/292/327: diferir solicitud hasta liquidación total."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"La carta se gestiona por deuda en backend/documentos, no solo CLIENTE/PANTALLA; 327 es candidata visual."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El requisito de SETTLED_CONFIRMED es explícito."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR solicitud cuando la deuda está liquidada coincide con elegibilidad."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"No representa estados de emisión, AVAILABLE para descarga, ni seguimiento por deuda de 212/327."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"REG_CLIENT_DEBT_SETTLEMENT_STATUS_001 y REG_CLIENT_NO_DEBT_LETTER_STATUS_001 exigen resolución autoritativa por deuda; no modela esas obligaciones."},"SEM_NO_DUPLICA":{"puntaje":0,"observacion":"REG_CLIENT_NO_DEBT_LETTER_STATUS_001 ya gobierna exactamente elegibilidad por SETTLED_CONFIRMED y ciclo documental; no se ha conciliado ese duplicado adicional."}}}},{"paquete":{"codigo":"REG_CHK_013","clave":"autorizacion_debito_cuotas","titulo":"Pago en cuotas exige autorizar el débito automático","descripcion":"En un plan en cuotas el botón de pago queda deshabilitado mientras el usuario no marque la autorización de cobro automático.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-LEGAL_NORMA","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/276,288","solicitante":"migracion-nucleo"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"modalidad_pago"},"der":{"lit":"CUOTAS"}},"der":{"op":"=","izq":{"hecho":"autoriza_debito_automatico"},"der":{"lit":false}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","autoriza_debito_automatico":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","autoriza_debito_automatico":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"PAGO_UNICO","autoriza_debito_automatico":false},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"276/288: bloquear CTA sin consentimiento."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"El contexto es cobro recurrente automático en checkout de cuotas; CLIENTE y modalidad CUOTAS abarcan también manual."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto comunica el requisito, aunque lo generaliza."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR cuando falta autorización coincide con el texto histórico."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"La condición traduce la generalización histórica pero no consulta el indicador backend de si requiere débito recurrente automático."},"SEM_NO_CONTRADICE":{"puntaje":0,"observacion":"REG_CLIENT_CHECKOUT_AUTODEBIT_CONSENT_CONTEXT_001 vigente: no exigir autorización en modalidad manual; el candidato bloquearía CUOTAS manual sin consentimiento. REG_CLIENT_CHECKOUT_INSTALLMENTS_VIEW_001 ratifica."},"SEM_NO_DUPLICA":{"puntaje":0,"observacion":"La regla vigente AUTODEBIT_CONSENT_CONTEXT_001 ya gobierna el requisito; falta reconciliación en vez de crear una versión más amplia."}}}},{"paquete":{"codigo":"REG_TEC_007","clave":"pago_requiere_conexion","titulo":"Sin conexión no se paga","descripcion":"Si el usuario pierde la conexión, el checkout bloquea el botón de pago y avisa que necesita conexión.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/183","solicitante":"migracion-nucleo"},"condicion":{"op":"=","izq":{"hecho":"conexion_disponible"},"der":{"lit":false}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"conexion_disponible":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"conexion_disponible":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"183: bloquear pago y avisar falta de conexión."},"CAL_ALCANCE":{"puntaje":0,"observacion":"183 también gobierna onboarding y guardado local; CLIENTE no distingue checkout de onboarding para la condición offline."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica la pérdida de conexión y respuesta de checkout."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR no expresa aviso y conservación de datos del original."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"conexion_disponible=false expresa pérdida/ausencia, no delimita checkout ni modela aviso."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"523: desconexión después de posible envío requiere reconciliación y no presupone ausencia de cargo. El candidato no distingue fases."},"SEM_NO_DUPLICA":{"puntaje":1,"observacion":"183 es la fuente declarada; no se detectó otro control idéntico de conectividad, aunque los deberes de reconciliación son complementarios."}}}},{"paquete":{"codigo":"REG_TEC_009","clave":"idempotencia_checkout","titulo":"Petición repetida dentro de la ventana no crea duplicados","descripcion":"Si el checkout se reenvía con la misma clave de idempotencia dentro de la ventana configurada, el servidor devuelve el resultado anterior sin crear otra operación.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-TECNICO","dueno":"PRODUCTO","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","efecto":"RECHAZAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/185","solicitante":"migracion-nucleo"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"clave_idempotencia_repetida"},"der":{"lit":true}},"der":{"op":"<","izq":{"hecho":"edad_clave_idempotencia"},"der":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}}},"pruebas":[{"casuistica":"BAJO_EL_LIMITE","entrada":{"clave_idempotencia_repetida":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":true},{"casuistica":"EN_EL_LIMITE","entrada":{"clave_idempotencia_repetida":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}},"esperado":false},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"clave_idempotencia_repetida":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":1}},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"185: devolver resultado anterior sin duplicados."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"185 también cubre submit Paso 1; el candidato BACKEND solo describe checkout."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Describe reenvío con clave y ventana configurada."},"COH_EFECTO":{"puntaje":0,"observacion":"RECHAZAR no equivale a reutilizar el resultado previo exitoso o pendiente de 185."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Usa parámetro real; < en el borde no está determinado expresamente en 185, y no representa misma operación/petición equivalente."},"SEM_NO_CONTRADICE":{"puntaje":0,"observacion":"185 y REG_ONB003_DNI_RESOLUTION_ATOMIC_001 requieren reutilización del resultado en reintento equivalente, no rechazo indiscriminado."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"B2B-RULE-IDEMP-001 y ONB003_DNI_RESOLUTION_ATOMIC ya cubren idempotencia en otros contextos; falta delimitar el contrato de checkout."}}}},{"paquete":{"codigo":"REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001","clave":"qr_confirmacion_autoritativa","titulo":"El QR solo se confirma con evidencia del proveedor","descripcion":"El botón \"Ya escaneé / Continuar\" solo consulta el estado; sin evidencia autoritativa del proveedor no se marca PAYMENT_CONFIRMED ni se crea otra operación.","familia":"PAYMENTS_CHECKOUT","naturaleza":"CONDUCTA","autoridad":"LEG-REVISION_FUNCIONAL","dueno":"PRODUCTO","alcance":"CLIENTE","modo":"HEREDA","clase":"PANTALLA","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/539,316","solicitante":"migracion-nucleo"},"condicion":{"op":"=","izq":{"hecho":"evidencia_autoritativa_pago"},"der":{"lit":false}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión del piloto","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"539/316: verificar mismo QR sin inventar confirmación."},"CAL_ALCANCE":{"puntaje":0,"observacion":"539 está en PANTALLA-28 QR; CLIENTE hereda en pantallas no QR sin predicado de contexto."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto distingue consulta y confirmación de pago."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR sin evidencia evita confirmación pero no expresa consulta, reconciliación y reutilización de referencia."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Solo evidencia_autoritativa_pago=false; no identifica QR, clic, referencia, expiración ni nueva operación (539)."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"REG_CHK_003 y REG_CLIENT_CHECKOUT_PROVIDER_HANDOFF_001 requieren estado real del proveedor. No se acredita protección de misma operación en estado pendiente."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"El origen 539/316 es intencional; REG_CHK_003 también cubre estados ambiguos; falta separar la operación QR especializada de la regla general."}}}}]$amjson$::jsonb) LOOP
  p:=item->'paquete'; j:=item->'juicio'; k:=p->>'codigo';
  g:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF g->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (g->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'AM_CHECKOUT_DOOR % %',k,g; END IF;
  v:=(g->>'version')::int;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=k AND version=v AND estado='CANDIDATA' AND ficha=p-'pruebas' AND origen=p->'origen' AND condicion=p->'condicion' AND efecto=p->>'efecto')
     OR (SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY nucleo_regla_pruebas.n) FROM lf_ops.nucleo_regla_pruebas WHERE regla=k AND version=v) IS DISTINCT FROM p->'pruebas'
     THEN RAISE EXCEPTION 'AM_CHECKOUT_PACKAGE_DRIFT %',k; END IF;
  h:=lf_ops.nucleo_hash_paquete_v1(k,v);
  -- Specific negative: a fabricated/stale hash must not be accepted.
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(j||jsonb_build_object('regla',k,'hash_evaluado',repeat('0',64),'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/checkout_am_juicios_v1.json'||' #'||k));
   RAISE EXCEPTION 'AM_CHECKOUT_BAD_HASH_ACCEPTED %',k;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  jr:=lf_ops.nucleo_juicio_registrar_v1(j||jsonb_build_object('regla',k,'hash_evaluado',h,'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/checkout_am_juicios_v1.json'||' #'||k));
  e:=lf_ops.nucleo_regla_evaluar_v1(k,true);
  IF j->>'veredicto'='DEVOLVER' AND e->>'decision' NOT IN ('DEVUELTA','BLOQUEADA') THEN RAISE EXCEPTION 'AM_CHECKOUT_NEGATIVE_JUDGE_BYPASSED % %',k,e; END IF;
  IF j->>'veredicto'='DEVOLVER' THEN
   BEGIN
    PERFORM lf_ops.nucleo_version_publicar_v1(k,v);
    RAISE EXCEPTION 'AM_CHECKOUT_UNSAFE_PUBLICATION %',k;
   EXCEPTION WHEN others THEN
    IF SQLERRM NOT LIKE 'NUCLEO_PUBLICAR_SIN_PROMOCION:%' THEN RAISE; END IF;
   END;
  END IF;
  -- Even an AUTO result does not switch the old path. Same-code legacy and
  -- nucleus would both show as VIGENTE in compatibility view; defer publication
  -- until explicit safe coexistence/cutover. No manual APROBAR is fabricated.
  RAISE NOTICE 'AM_CHECKOUT_RESULT %', jsonb_build_object('codigo',k,'version',v,'hash',h,'juicio',j->>'veredicto','juicio_id',jr->'juicio_id','evaluacion',e->>'decision','nota',e->'nota','componentes',e->'componentes','motivos',e->'motivos','origen',p->'origen');
 END LOOP;
 SELECT count(*) INTO n FROM lf_ops.nucleo_reglas WHERE familia='PAYMENTS_CHECKOUT' AND estado='CANDIDATA' AND regla_legacy_id IS NULL;
 IF n<>10 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_CUO_003' OR estado='VIGENTE') THEN RAISE EXCEPTION 'AM_CHECKOUT_SCOPE_DRIFT %',n; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_juicios j JOIN lf_ops.nucleo_regla_versiones v ON v.regla=j.regla AND v.version=j.version WHERE v.estado='CANDIDATA' AND j.hash_evaluado=lf_ops.nucleo_hash_paquete_v1(j.regla,j.version))<>10 THEN RAISE EXCEPTION 'AM_CHECKOUT_JUDGMENT_READBACK'; END IF;
 IF EXISTS(SELECT id,codigo,categoria,titulo,descripcion,razon,valor_config,es_transversal,estado,origen,created_at,updated_at,pendiente_decision,pendiente_detalle,created_by FROM lf_ops.reglas EXCEPT ALL SELECT id,codigo,categoria,titulo,descripcion,razon,valor_config,es_transversal,estado,origen,created_at,updated_at,pendiente_decision,pendiente_detalle,created_by FROM lf_ops.v_reglas_compat_v1) THEN RAISE EXCEPTION 'AM_CHECKOUT_LEGACY_VIEW_LOSS'; END IF;
 RAISE NOTICE 'AM_CHECKOUT_PASS 10 candidates, 10 current-context judgments, 10 evaluations; legacy view preserved, zero publication';
END $am$;
COMMIT;
